import React from "react";
import { AbsoluteFill } from "remotion";
import type { TransitionPresentation, TransitionPresentationComponentProps } from "@remotion/transitions";
import { film } from "../film";
import { C } from "../theme";
import { interp, OUT } from "../lib/anim";

type P = { seed?: number };

/** The signature transition. The engine's own 5x5 pulli kolam (one closed line around 25 dots, generated by the app)
 *  is drawn in chalk over the outgoing shot; the moment the line closes, the inside of the loop fills with lamplight and
 *  opens like an iris onto the next scene. Progress p runs 0..1 over the transition. */
const Kolam: React.FC<TransitionPresentationComponentProps<P>> = ({ children, presentationDirection, presentationProgress: p }) => {
  if (presentationDirection === "exiting") {
    // the outgoing shot dims toward dusk while the line is drawn
    const dim = interp(p, [0, 0.6], [0, 0.55]);
    return (
      <AbsoluteFill>
        {children}
        <AbsoluteFill style={{ background: C.night950, opacity: dim }} />
      </AbsoluteFill>
    );
  }
  const k = film.kolam;
  const S = 760 / k.view; // the kolam is drawn 760 px tall, centred
  const dots = interp(p, [0, 0.14], [0, 1], OUT);
  const line = interp(p, [0.06, 0.6], [0, 1], OUT);
  const iris = interp(p, [0.58, 1], [0, 1], OUT);
  const R = iris * 1400; // iris radius in px
  const glow = interp(p, [0.5, 0.62, 0.9], [0, 1, 0]);
  const fadeChalk = 1 - interp(p, [0.75, 1], [0, 1]);
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ clipPath: `circle(${R}px at 960px 540px)` }}>{children}</AbsoluteFill>
      <svg width={1920} height={1080} style={{ position: "absolute", inset: 0 }}>
        <defs>
          <radialGradient id="kl-glow">
            <stop offset="0%" stopColor={C.flame} stopOpacity={0.9} />
            <stop offset="45%" stopColor={C.marigold} stopOpacity={0.55} />
            <stop offset="100%" stopColor={C.marigold} stopOpacity={0} />
          </radialGradient>
        </defs>
        <circle cx={960} cy={540} r={260 + 500 * glow} fill="url(#kl-glow)" opacity={glow * 0.8} />
        <g transform={`translate(${960 - (k.view * S) / 2}, ${540 - (k.view * S) / 2}) scale(${S})`} opacity={fadeChalk}>
          {k.dots.map(([x, y], i) => (
            <circle key={i} cx={x} cy={y} r={10.5} fill={C.chalk} opacity={interp(dots, [i / 40, i / 40 + 0.4], [0, 1])} filter="url(#chalk)" />
          ))}
          <path d={k.d} pathLength={1} fill="none" stroke={C.chalk} strokeWidth={7 / S * 0.9} strokeLinecap="round" strokeLinejoin="round"
            strokeDasharray="1 1" strokeDashoffset={1 - line} filter="url(#chalk)" />
          <path d={k.d} pathLength={1} fill="none" stroke={C.marigold400} strokeWidth={14 / S} strokeLinecap="round"
            strokeDasharray="0.012 0.988" strokeDashoffset={1 - line + 0.006} opacity={line > 0 && line < 1 ? 0.9 : 0} />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export const kolamLoop = (): TransitionPresentation<P> => ({ component: Kolam, props: {} });
